"""Cleaning step of the orders ETL."""

import pandas as pd


def _clean_text(value):
    if isinstance(value, str):
        value = value.strip()
        return pd.NA if value == "" else value
    return value


def clean_orders(df: pd.DataFrame) -> pd.DataFrame:
    """A copy of ``df`` with text trimmed, blank text missing and missing qty 0."""
    out = df.copy()
    for col in out.select_dtypes(include=["object", "string"]).columns:
        if isinstance(out[col].dtype, pd.StringDtype):
            stripped = out[col].str.strip()
            out[col] = stripped.mask(stripped == "")
        else:
            # Object columns can hold non-strings; only touch the strings.
            out[col] = out[col].map(_clean_text).astype(object)
    if "qty" in out.columns:
        out["qty"] = out["qty"].fillna(0)
    return out

